from pathlib import Path
import json

root = Path(__file__).resolve().parent.parent
def read(p): return json.loads((root/p).read_text(encoding='utf-8-sig'))
def ru(s):
    try: return json.loads(s).get('ru') or 'не указано'
    except: return s or 'не указано'
tracks = read('docs/tracks-api.json')['data']
head = '# Актуальные треки — 23.09.2026\n\nИсточник: https://edu.astanahub.com/hackathons/df4743f5-c492-415c-b45a-1f13adb78e06?tab=tracks и публичный API core.spira.to.\n\nПолучено напрямую ведущим, не ручная вставка. Полные условия недоступны в неавторизованном ответе: description пусто, requirements и criteria null. Это НЕ означает отсутствия требований у организаторов. Нумерация — position + 1 на актуальном сайте; она не совпадает с context/ideas и context/tracks.\n\n'
out=[head]
for t in tracks:
    n=t['position']+1
    out.append(f'## Трек {n:02d}: {ru(t["title"])}\n\nID трека: `{t["id"]}`.\n')
    for c in read(f'docs/tracks_raw/{t["id"]}.json')['data']:
        out.append(f'### Задача {c["position"]+1:02d}: {ru(c["title"])}\n\nID задачи: `{c["id"]}`.\n\n')
        partner={4:'Beeline (в названии задачи; отдельное поле заказчика отсутствует)',11:'Казактелеком (в названии спецтрека)',12:'Astana Innovations (в названии спецтрека)'}.get(n,'не указано')
        out.append(f'- Партнёр/заказчик: {partner}.\n')
        for label in ['Полная формулировка','Вход','Выход','Предоставленные данные или API','Особые критерии оценки','Ограничения']:
            out.append(f'- {label}: не указано в доступном ответе API; требуется текст из авторизованного кабинета.\n')
        out.append(f'- Источник: https://core.spira.to/hackathons/api/v1/hackathons/df4743f5-c492-415c-b45a-1f13adb78e06/tracks/{t["id"]}/cases\n\n')
(root/'docs/TRACKS_LIVE.md').write_text(''.join(out),encoding='utf-8')
(root/'docs/TRACKS_PARSED.md').write_text(''.join(out),encoding='utf-8')

